local ActivityCatGirlPKVoteRewardDialog = Class("ActivityCatGirlPKVoteRewardDialog")
---@type ActivityMgr
local ActivityMgr = import('Game.Activity.ActivityMgr'):GetInstance()
---@type ActivityVoteComponent
local ActivityVoteComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.ActivityVoteComponent)
function ActivityCatGirlPKVoteRewardDialog:__init()
	self._activityUuid = 0
	self._activityId = 0               --当前活动id
	self._allReward = {}            --所有的奖励
end

function ActivityCatGirlPKVoteRewardDialog:__delete()
	self._activityUuid = nil
	self._activityId = nil
	self._allReward = nil
end

function ActivityCatGirlPKVoteRewardDialog:Awake()
    local activityId = ActivityVoteComponent:GetActivityUuid()
	self.activityDojo = ActivityMgr:GetActivityComponent():GetDojoByActivityId(activityId)
	self._activityId = activityId
	if self._activityId == 0 then
		return
	end
	if not isNull(self._timeDown) then
		CDTimerModule.GetInstance():RemoveCD(self._timeDown)
		self._timeDown = nil
	end
    local voteGoodsId =  ActivityVoteComponent:GetVoteGoodsId()
    local path = GoodsConfMgr:GetInstance():GetPhotoPathById(voteGoodsId)
    CfUtils.FillImage(self.ImgIcon , path)
    CfUtils.FillImage(self.ImgBg , "Arts/Textures/ActivityCatGirlPK12003201/activity_2024pk_reward_bg.png")
    CfUtils.FillText(self.TexNumber  , ActivityVoteComponent:GetDojo().myVoteNum)
    
	self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
		self:FillTime()
	end, 2592000, false, true)
end

function ActivityCatGirlPKVoteRewardDialog:FillTime()
	local serverTime = GameUtils.GetServerTime()
	local num = checkNumber(self.activityDojo.closeTime) - checkNumber(serverTime)
	if num < 0 then
		num = 0
	end
	CfUtils.FillText(self.Text2, CfUtils.GetTimeHMS4(num))
end

function ActivityCatGirlPKVoteRewardDialog:RefreshShow()
	self:TaskHomeResponseHandler()
end

function ActivityCatGirlPKVoteRewardDialog:TaskHomeResponseHandler()
    local atterdRewards  = ActivityVoteComponent:GetSortAttendRewards()
    self.taskData = {}
    for i =1 , #atterdRewards -1 do
        self.taskData[i] = atterdRewards[i]
    end
    self.maxData = atterdRewards[#atterdRewards]
    table.sort(self.taskData , function ( a , b)
        local aStatus = a.status == 2 and -1 or  a.status 
        local bStatus = b.status == 2 and -1 or  b.status 
        if aStatus > bStatus then
            return true 
        elseif aStatus < bStatus then
            return false
        else 
            return checkInt(a.id ) < checkInt(b.id) 
        end
    end)
    
    self:FillSelf()
end

function ActivityCatGirlPKVoteRewardDialog:FillSelf()	
	self:FillTime()
	
	self:FillCellShow()
	
	self.TaskList:InitListView(table.count(self.taskData), Bind(self, self.OnGetItemByIndex))
	
	SetButtonAction(self.FontStyleButton, Bind(self, self.OneKeyReward))
end

function ActivityCatGirlPKVoteRewardDialog:FillCellShow()
	local count = #self.taskData
	local data = self.maxData
	local env = CfUtils.GetLuaScr(self.ResidentCell, UITaskCellPath)
	if isNotNull(env) then
		env:Refresh(data, Bind(self,self.OnMaxTaskCellClick), count)
	end
	CfUtils.SetActive(self.ResidentCell.gameObject, true)
end

function ActivityCatGirlPKVoteRewardDialog:OneKeyReward()
	local isHaveReward = self:IsHaveTaskReward()
	if isHaveReward then
		local activityId = self._activityId
		local data = {activityUuid = activityId, rewardId = 0}
		GameUtils.Request(Interfaces.ActivityVoteDrawAttendReward, data,function(request,response)
			if checkNumber(response.errCode) ~= 0 then return end
			local jsonData = response.data
			local rewards = checkTable(jsonData.rewards)
			if #rewards > 0 then
				GoodsUtils.DrawRewards(rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
			end
			self:RefreshTaskShow()
		end)
	else
		GameUtils.Toast(localize("暂无可领取的奖励"))
	end
end

function ActivityCatGirlPKVoteRewardDialog:RefreshTaskShow()
	for i, v in ipairs(self.taskData) do
		if v.status == 1 then
			v.status = 2
		end
	end
	
	if self.maxData.status == 1  then
		self.maxData.status = 2
	end
	
	GameUtils.ReloadData(self.TaskList, table.count(self.taskData))
	self:FillCellShow()
	self:UpdateRedPoint()
end

function ActivityCatGirlPKVoteRewardDialog:IsHaveTaskReward()
	for i, v in ipairs(self.taskData) do
		if v.status == 1 then
			return true
		end
	end
	
	if self.maxData.status == 1 then
		return true
	end
	return false
end

function ActivityCatGirlPKVoteRewardDialog:OnGetItemByIndex(listView, index)
	if index < 0 then
		return
	end
	local cell = listView:NewListViewItem("Cell")
	local scr = CfUtils.GetLuaScr(cell.gameObject, UITaskCellPath)
	local data = self.taskData[index + 1]
	if scr then
		scr:Refresh(data, Bind(self,self.OnTaskCellClick),index + 1)
	end
	
	return cell
end

function ActivityCatGirlPKVoteRewardDialog:OnTaskCellClick(index)
	local data = self.taskData[index]
	if data.status == 2 then
		GameUtils.Toast(localize("奖励已领取"))
		return
	end
	if data.status == 1 then
		local activityId = self._activityId
		local serverData = {activityUuid = activityId, rewardId = data.id}
		GameUtils.Request(Interfaces.ActivityVoteDrawAttendReward, serverData,function(request,response)
			if checkNumber(response.errCode) ~= 0 then return end
			local jsonData = response.data
			data.status = 2
			local rewards = checkTable(jsonData.rewards)
			if #rewards > 0 then
				GoodsUtils.DrawRewards(rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
			end
			GameUtils.ReloadData(self.TaskList, table.count(self.taskData))
			self:FillCellShow()
			self:UpdateRedPoint()
		end)
	else
		GameUtils.Toast(localize("未达成领取条件"))
	end
end

function ActivityCatGirlPKVoteRewardDialog:OnMaxTaskCellClick()
	local data = self.maxData
	if data.status == 2 then
		GameUtils.Toast(localize("奖励已领取"))
		return
	end
	if data.status == 1 then
		local serverData = {activityUuid = self._activityId, rewardId = data.id}
		GameUtils.Request(Interfaces.ActivityVoteDrawAttendReward, serverData,function(request,response)
			if checkNumber(response.errCode) ~= 0 then return end
			local jsonData = response.data
			data.status = 2
			local rewards = checkTable(jsonData.rewards)
			if #rewards > 0 then
				GoodsUtils.DrawRewards(rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
			end
			self:FillCellShow()
			self:UpdateRedPoint()
		end)
	else
		GameUtils.Toast(localize("未达成领取条件"))
	end
end

function ActivityCatGirlPKVoteRewardDialog:UpdateRedPoint()
	local taskTips = -1
	for i, v in ipairs(self.taskData) do
		if v.status == 1 then
			taskTips = 0
			break
		end
	end
	-- JapaneseStoryMgr:SetAchievementTaskTips(taskTips)
end

